misconfigured_snippet:
file { $fragdir: ensure => directory, mode => "0775", }
file { "${fragdir}/fragments": ensure => directory, mode => "0775", force => true, ignore => ['.svn', '.git', '.gitignore'], notify => exec["concat_${name}"], purge => true, recurse => true, source => $source_real, }
file { "${fragdir}/fragments.concat": ensure => present, mode => "0664", }
file { "${fragdir}/${concat_name}": ensure => present, mode => "0664", }

python::virtualenv { "$db_maintenance_dir":
  python   => "${packages::mozilla::python27::python}",
  require  => class['packages::mozilla::python27'],
  user     => "${users::builder::username}",
  group    => "${users::builder::group}",
  packages => [
    "sqlalchemy==0.7.9",
    "mysql-python==1.2.3",
  ];
}

file { $alarm_definition_config: ensure => file, content => template($alarm_definition_config_source), mode => '0755', owner => 'root', group => 'root', }
file { $notification_config: ensure => file, content => template($notification_config_source), mode => '0755', owner => 'root', group => 'root', }
file { $notification_assignments: ensure => file, content => template($notification_assignments_source), mode => '0755', owner => 'root', group => 'root', }

$password = $scaleio['password']
if $scaleio['existing_cluster'] {
  $client_password = $password
} else {
  $client_password_str = base64('encode', pw_hash($password, 'sha-512', 'scaleio.client.access'))
  $client_password = inline_template('sio-<%= @client_password_str[33..40] %>-<%= @client_password_str[41..48] %>')
}
...
class {'::scaleio_openstack::nova':
  ensure => present,
  gateway_user => $::gateway_user,
  gateway_password => $client_password,
  gateway_ip => $gateway_ip,
  gateway_port => $::gateway_port,
  protection_domains => $pd_name,
  storage_pools => $::storage_pools,
  provisioning_type => $provisioning_type,
}

if $libvirt_vif_driver == 'nova.virt.libvirt.vif.libvirtgenericvifdriver' and $force_snat_range {
  $force_snat_range_array = split($force_snat_range, '/')
  if is_ip_address($force_snat_range_array[0]) and is_integer($force_snat_range_array[1]) {
    nova_config { 'default/force_snat_range': value => $force_snat_range; }
  } else {
    fail('force_snat_range should be ipv4 or ipv6 cidr notation')
  }
}

openstack::ha::haproxy_service { 'heat-api': order => '160', listen_port => 8004, }
openstack::ha::haproxy_service { 'heat-api-cfn': order => '161', listen_port => 8000, }
openstack::ha::haproxy_service { 'heat-api-cloudwatch': order => '162', listen_port => 8003, }

firewall {'500 zookeeper ports': port => '2888-3888', proto => 'tcp', action => 'accept', require => class['::zookeeper'] }
firewall {'501 zookeeper ports': port => '2181', proto => 'tcp', action => 'accept', require => class['::zookeeper'] }
firewall {'550 cassandra ports': port => '9042', proto => 'tcp', action => 'accept', require => class['::cassandra'] }
firewall {'551 cassandra ports': port => '7000', proto => 'tcp', action => 'accept', require => class['::cassandra'] }
firewall {'552 cassandra ports': port => '7199', proto => 'tcp', action => 'accept', require => class['::cassandra'] }
firewall {'553 cassandra ports': port => '9160', proto => 'tcp', action => 'accept', require => class['::cassandra'] }
firewall {'554 cassandra ports': port => '59471', proto => 'tcp', action => 'accept', require => class['::cassandra'] }

package {'murano-glance-artifacts-plugin': ensure => 'latest', }
package {'python-app-catalog-ui': ensure => 'latest', }
class { '::murano::dashboard': enable_glare => $use_glare, repo_url => $repository_url, sync_db => false, package_ensure => 'latest' }

$libvirt_vnc_bind_host = hiera('config_ip_version') ? { 'ipv6' => '::0', default => '0.0.0.0', }
class { '::nova::compute::libvirt':
  libvirt_virt_type      => $libvirt_virt_type,
  vncserver_listen       => $libvirt_vnc_bind_host,
  migration_support      => true,
  libvirt_inject_partition => '-1',
}
